//! The flag table, and it is the *only* place a flag is written down.
//!
//! `docs/cli.md`, "The manual", makes the manual page autogenerated, current
//! and drift-free as three separate obligations, and the third — drift-free —
//! is the one that fails silently. The way all three hold is that there is
//! exactly one list here and two renderers walk it:
//!
//! * `--help` renders it, via [`crate::help`].
//! * `podssh man` renders it, via [`crate::man`], as text and as roff.
//!
//! A flag defined here and unimplemented is a refusal naming itself. It is
//! never a stub that exits 0 (`docs/cli.md`, "Exit codes"), and `refuse::refused` is
//! where the refusal text comes from.
//!
//! The rows are checked by `tests/flag_table.rs` (the `ssh` short flags are a
//! reviewed list there) and by the help and man page parity tests. The
//! specification they were once matched against is archived.

/// What a flag does, in enough words for a man page and short enough for help.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FlagKind {
    /// A flag that is fully wired. It parses and it is handed to the session.
    Supported,
    /// A flag that parses and is deliberately ignored, and says so.
    Accepted,
    /// A real OpenSSH flag podssh does not implement in this release. It parses,
    /// and using it is a refusal naming what to use instead.
    Refused,
    /// A flag that exists in OpenSSH's vocabulary and podssh will not carry.
    /// It never parses; mentioning it names `-W`.
    NotInFirstRelease,
}

/// One row of the table. `Option<&str>` for `short` because some flags are long
/// only (`--StrictHostKeyChecking`, `--timeout`, `--jsonl`, and the flags of `relay`).
#[derive(Clone, Copy, Debug)]
pub struct FlagRow {
    pub short: Option<char>,
    pub long: &'static str,
    /// The metavariable after the flag in a man page: `PORT`, `FILE`, `TAG`.
    pub arg: Option<&'static str>,
    pub kind: FlagKind,
    /// The help text. One line, no trailing period — `ssh` writes them without.
    pub help: &'static str,
    /// For a `Refused` row, what the user should type instead.
    pub instead: Option<&'static str>,
}

impl FlagRow {
    /// The flag as a user types it, for messages and for the man emitter.
    pub fn spelling(&self) -> String {
        match self.short {
            Some(c) => format!("-{c}"),
            None => format!("--{}", self.long),
        }
    }

    /// The spelling with its metavariable, as it appears in `Usage:`.
    pub fn usage_form(&self) -> String {
        match self.arg {
            Some(a) => format!("{} {a}", self.spelling()),
            None => self.spelling(),
        }
    }
}

const fn row(
    short: Option<char>,
    long: &'static str,
    arg: Option<&'static str>,
    kind: FlagKind,
    help: &'static str,
    instead: Option<&'static str>,
) -> FlagRow {
    FlagRow { short, long, arg, kind, help, instead }
}

/// **The one-line description of the whole program**, and it is here rather
/// than in a renderer because two renderers write it: `--help`'s banner and
/// the page's `.SH NAME` (`podssh man --roff`). A sentence copied into both is a sentence
/// that drifts, and this one names the program's whole premise.
pub const ABOUT: &str = "no-privilege SSH over a WebSocket relay";

/// **The universal option, written down once.** Every verb accepts
/// `--help`; it is not a row in any verb's table because the *parser* declares
/// it ([`crate::tree::verb_command`]) rather than parsing it from a table.
/// `podssh man` renders it for every section, and `--help` renders it for
/// every verb, so the sentence lives here and the parity gate compares the
/// two renderings of it rather than trusting either copy.
pub const HELP_FLAG: FlagRow = row(
    None,
    "help",
    None,
    FlagKind::Supported,
    "Print help for this subcommand and exit",
    None,
);

/// **`ssh`'s flags, one row for each OpenSSH flag (`docs/cli.md`, "Options of `podssh ssh`").**
///
/// **The `-P` row is `Accepted`, not `Refused`, and it is `TAG`.** The
/// entry's premise said `-P` is not an OpenSSH flag and must be refused; the
/// specification has since been corrected (see `docs/cli.md`, "Options of `podssh ssh`"), and
/// the correction is right. MEASURED 2026-10-02, this machine, Git Bash on
/// Windows, OpenSSH_10.3p1:
///   `ssh -G -P mytag example.org` → `tag mytag`; without `-P` there is no
///   `tag` line at all. `ssh -G -P2222 example.org` → `port 22`, `tag 2222`.
/// **Refusing it would refuse a flag a user has memorised and that OpenSSH
/// honours**, which breaks the parity promise the whole entry exists for.
/// `-P` remains `scp`'s port (SCP_FLAGS, which T-139 adds), which is why the refusal
/// below is per-verb and never global.
