/// One verb: its names, its flags, and the flag table its `-P` belongs to.
#[derive(Clone, Copy)]
pub struct Verb {
    /// The canonical name, and the one `--help` prints.
    pub name: &'static str,
    /// Every spelling that resolves to this verb, such as `irc` for `chat`, and
    /// `scp` and `sftp` for `cp`. `podssh man` prints them as "Other names" of
    /// each command.
    pub aliases: &'static [&'static str],
    pub flags: &'static [FlagRow],
    pub about: &'static str,
}

/// **Every verb, in the order `--help` prints them.** `aliases` is how the
/// no-subcommand handler finds a verb, and it is the same list the distance
/// stage searches — one list, so a verb the handler cannot suggest is a verb
